import pandas as pd

def clean(df):
    df = df.copy()

    if "island" in df.columns:
        df["island"] = (
            df["island"].astype("string").str.strip().str.title()
            .replace({"Torgerson": "Torgersen", "Bisco": "Biscoe"})
        )

    if "sex" in df.columns:
        df["sex"] = (
            df["sex"].astype("string").str.strip().str.lower()
            .replace({"female": "female", "male": "male"})
        )

    if "body_mass_g" in df.columns:
        df["body_mass_g"] = pd.to_numeric(
            df["body_mass_g"].astype("string").str.replace(",", "", regex=False),
            errors="coerce"
        )

    for col in ["flipper_length_mm", "year"]:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors="coerce")

    df = df.drop_duplicates()
    if "penguin_id" in df.columns:
        df = df.drop_duplicates(subset=["penguin_id"], keep="first")

    return df

def answer(df):
    d = clean(df)
    d = d.dropna(subset=["island"])
    counts = d.groupby("island", dropna=True).size()
    return {str(k): int(v) for k, v in counts.items()}
